# gen_kernel_text.py (Push A's fclink folder, 2026-11-21, written by the assistant from the research prototype
# clink's generator of the same name; its header and the generated file's header changed after review 1 (m1, m10);
# the cutting, checking and quoting did not). Standard library only.
# Reads sweep_fc2.c, takes the two lines strictly between "/* BEGIN COQ TEXT */" and "/* END COQ TEXT */", and prints
# KernelText.v: each line as a Coq string, so that Link.v can prove that the line is CPrint.v's printed text of the
# frozen shape (FC_TEXT in FCLINK_Statement.v). The design proves it with vm_compute: Coq's virtual machine at coqc,
# and Coq's conversion again, without the virtual machine, under coqchk (TRUSTED.md, section 4). It understands
# nothing of C: it cuts, checks the characters, and quotes. A Coq string literal stands for its characters one for
# one, except a double quote, which Coq writes twice; this script refuses a double quote, so each quoted line is the
# line's bytes.
# Refuses (exit 1, nothing printed): a file that is not ASCII; a marker absent, twice, or not alone on its line; not
# exactly two lines between the markers; a line that does not begin with its function's head or end with "; }"; a
# character outside printable ASCII; a double quote.
#   python -B gen_kernel_text.py              reads sweep_fc2.c beside this script (gate4's "generated" row runs it so,
#                                             with no argument, from a temporary working folder)
#   python -B gen_kernel_text.py <sweep.c>    reads another file (used to make the plants' KernelText files)
import os, sys
B, E = '/* BEGIN COQ TEXT */', '/* END COQ TEXT */'
HEADS = (('floor32_c_text', 'static double mk_floor32(double x) { return '),
         ('ceil32_c_text', 'static double mk_ceil32(double x) { return '))

def region(path):
    t = open(path, 'rb').read().decode('ascii')
    lines = t.split('\n')
    if lines.count(B) != 1 or lines.count(E) != 1: raise ValueError('each marker exactly once, alone on its line')
    i, j = lines.index(B), lines.index(E)
    if j < i: raise ValueError('the END marker comes before the BEGIN marker')
    body = lines[i + 1:j]
    if len(body) != len(HEADS): raise ValueError('%d lines between the markers, %d expected' % (len(body), len(HEADS)))
    for (name, head), ln in zip(HEADS, body):
        if not ln.startswith(head) or not ln.endswith('; }'): raise ValueError('line for %s has the wrong head or end' % name)
        if any(not (32 <= ord(c) < 127) for c in ln) or '"' in ln: raise ValueError('line for %s: a character outside the set' % name)
    return body

def kernel_text(path):
    body = region(path)
    out = ['(* Generated by fclink/gen_kernel_text.py (written by the assistant, 2026-11-21) from fclink/%s;' % os.path.basename(path),
           '   do not edit. The two lines between the sweep program\'s COQ TEXT markers, byte for byte, as Coq strings.',
           '   FC_TEXT in FCLINK_Statement.v states each equal to CPrint.v\'s printed text of the frozen shape; this file',
           '   only quotes them: no proof script, nothing assumed. *)',
           'From Coq Require Import String.', 'Local Open Scope string_scope.', '']
    for (name, _), ln in zip(HEADS, body):
        out.append('Definition %s : string :=' % name)
        out.append('  "%s".' % ln)
    return ('\n'.join(out) + '\n').encode('ascii')

if __name__ == '__main__':
    try:
        src = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), 'sweep_fc2.c')
        sys.stdout.buffer.write(kernel_text(src))
    except (ValueError, OSError, UnicodeDecodeError, IndexError) as e:
        sys.stderr.write('gen_kernel_text.py: REFUSED: %s\n' % e); sys.exit(1)
